                    ObjCVarvwReceivablesTank.mReceiptNo = Convert.ToString(dr["ReceiptNo"].ToString());
                    ObjCVarvwReceivablesTank.mReceiptDate = Convert.ToDateTime(dr["ReceiptDate"].ToString());
                    ObjCVarvwReceivablesTank.mIsLocked = Convert.ToInt32(dr["IsLocked"].ToString());
                    ObjCVarvwReceivablesTank.mSalesAmountAfterInvoiceTax = Convert.ToDecimal(dr["SalesAmountAfterInvoiceTax"].ToString());
                    TotRecs = Convert.ToInt32(dr["TotalRecords"].ToString());
                    lstCVarvwReceivablesTank.Add(ObjCVarvwReceivablesTank);
                }
            }
            catch (Exception ex)
            {
                Exp = ex;
            }
            finally
            {
                if (dr != null)
                {
                    dr.Close();
                    dr.Dispose();
                }
            }
            tr.Commit();
        }
        catch (Exception ex)
        {
            Exp = ex;
        }
        finally
        {
            Con.Close();
            Con.Dispose();
        }
        return Exp;
    }

    #endregion
